// vertical pass

#define SAMPLE 16.0

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 color = vec4(0.0);
    vec2 m_normal = iMouse.xy/iResolution.xy;
    vec2 uv = fragCoord/iResolution.xy;
    for (float i = -SAMPLE; i < SAMPLE; i++)
    {
        color += texture(iChannel0, uv + vec2(0.0, i/250.0) * m_normal.x);
    }
    color /= SAMPLE*2.0;
    fragColor = color;
}

// horizontal pass

#define SAMPLE 16.0

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 color = vec4(0.0);
    vec2 m_normal = iMouse.xy/iResolution.xy;
    vec2 uv = fragCoord/iResolution.xy;
    for (float i = -SAMPLE; i < SAMPLE; i++)
    {
        color += texture(iChannel0, uv + vec2(i/250.0, 0.0) * m_normal.x);
    }
    color /= SAMPLE*2.0;
    fragColor = color;
}
